string schemeKw = args != null && args.ContainsKey("schemeKeyword") && args["schemeKeyword"] != null ? args["schemeKeyword"].ToString().ToUpper() : "";
var areas = new FilteredElementCollector(doc).OfCategory(BuiltInCategory.OST_Areas).WhereElementIsNotElementType().Cast<SpatialElement>().Where(a=>a.Area>0).ToList();
var schemes = areas.Select(a=>((Area)a).AreaScheme?.Name).Distinct().ToList();
var aRows = areas.Where(a=> schemeKw=="" || (((Area)a).AreaScheme?.Name??"").ToUpper().Contains(schemeKw))
 .GroupBy(a=> new { scheme=((Area)a).AreaScheme?.Name, level=a.Level?.Name })
 .Select(g=> new { g.Key.scheme, g.Key.level, count=g.Count(), areaM2=Math.Round(g.Sum(a=>a.Area)*0.09290304,2),
   byName = string.Join("; ", g.GroupBy(a=>a.LookupParameter("Name")?.AsString()).Select(x=> x.Key+"="+Math.Round(x.Sum(a=>a.Area)*0.09290304,1))) }).OrderBy(x=>x.scheme).ThenBy(x=>x.level).ToList();
var rooms = new FilteredElementCollector(doc).OfCategory(BuiltInCategory.OST_Rooms).WhereElementIsNotElementType().Cast<SpatialElement>().Where(r=>r.Area>0)
 .GroupBy(r=>r.Level?.Name).Select(g=> new { level=g.Key, rooms=g.Count(), areaM2=Math.Round(g.Sum(r=>r.Area)*0.09290304,1),
   balconyCoveredNo = Math.Round(g.Where(r=> (r.LookupParameter("SIEC_DM_SpaceUsageCode")?.AsString()??"")=="SC_30_20_15" && (r.LookupParameter("SIEC_DM_IsCovered")?.AsString()??"")!="Yes").Sum(r=>r.Area)*0.09290304,1) }).ToList();
var balc = new FilteredElementCollector(doc).OfCategory(BuiltInCategory.OST_Rooms).WhereElementIsNotElementType().Cast<SpatialElement>().Where(r=>r.Area>0 && ((r.LookupParameter("SIEC_DM_SpaceUsageCode")?.AsString()??"").StartsWith("SC_30_20")))
 .GroupBy(r=> (r.LookupParameter("SIEC_DM_SpaceUsageCode")?.AsString())+" covered="+(r.LookupParameter("SIEC_DM_IsCovered")?.AsString()??"(empty)")+" lightweight="+(r.LookupParameter("SIEC_DM_IsLightWeightCovering")?.AsString()??"(empty)")).Select(g=> g.Key+": "+g.Count()).ToList();
return new { schemes, areas=aRows, rooms, balconyFlags=balc };

var imports = new FilteredElementCollector(doc).OfClass(typeof(ImportInstance)).Cast<ImportInstance>().ToList();
var result = new List<object>();
var opt = new Options(); opt.IncludeNonVisibleObjects = false;
foreach (var imp in imports) {
  var typeName = doc.GetElement(imp.GetTypeId())?.Name;
  var counts = new Dictionary<string,int>();
  var closedPolys = new Dictionary<string,int>();
  var ge = imp.get_Geometry(opt);
  foreach (var g in ge) {
    var gi = g as GeometryInstance; if (gi == null) continue;
    foreach (var o in gi.GetInstanceGeometry()) {
      string layer = "";
      var gs = doc.GetElement(o.GraphicsStyleId) as GraphicsStyle;
      if (gs != null) layer = gs.GraphicsStyleCategory?.Name ?? "";
      string key = o.GetType().Name + " | " + layer;
      counts[key] = counts.ContainsKey(key) ? counts[key]+1 : 1;
      if (o is PolyLine pl) {
        var pts = pl.GetCoordinates();
        if (pts.Count > 2 && pts[0].IsAlmostEqualTo(pts[pts.Count-1])) closedPolys[layer] = closedPolys.ContainsKey(layer) ? closedPolys[layer]+1 : 1;
      }
    }
  }
  result.Add(new { id = imp.Id.IntegerValue, type = typeName, isLinked = imp.IsLinked, viewSpecific = imp.ViewSpecific, ownerView = imp.OwnerViewId.IntegerValue, geometry = counts, closedPolylinesByLayer = closedPolys });
}
return result;

