string srcName = args != null && args.ContainsKey("sourceSetup") ? (string)args["sourceSetup"] : "DM Export";
string tgtName = args != null && args.ContainsKey("targetSetup") ? (string)args["targetSetup"] : "IFC Configuration - DM Export MK";
string[] keys = { "ExchangeRequirement", "SplitWallsAndColumns", "ExportIFCCommonPropertySets", "ExportSpecificSchedules", "ExportUserDefinedPsetsFileName", "SitePlacement" };
var schema = Autodesk.Revit.DB.ExtensibleStorage.Schema.ListSchemas().FirstOrDefault(s => s.SchemaName == "IFCExportConfigurationMap");
if (schema == null) throw new Exception("IFC export schema not found");
var field = schema.GetField("MapField");
Autodesk.Revit.DB.ExtensibleStorage.DataStorage tgtDs = null; string srcJson = null, tgtJson = null;
foreach (Autodesk.Revit.DB.ExtensibleStorage.DataStorage d in new FilteredElementCollector(doc).OfClass(typeof(Autodesk.Revit.DB.ExtensibleStorage.DataStorage))) {
  var ent = d.GetEntity(schema); if (ent == null || !ent.IsValid()) continue;
  var j = ent.Get<string>(field);
  if (j.Contains("\"Name\":\"" + srcName + "\"")) srcJson = j;
  if (j.Contains("\"Name\":\"" + tgtName + "\"")) { tgtDs = d; tgtJson = j; }
}
if (srcJson == null || tgtJson == null) throw new Exception("Source or target setup not found");
Func<string,string,string> tok = (json, key) => {
  string marker = "\"" + key + "\":";
  int i = json.IndexOf(marker); if (i < 0) throw new Exception("Key not found: " + key);
  if (json.IndexOf(marker, i + 1) >= 0) throw new Exception("Key not unique: " + key);
  int start = i + marker.Length; int end = json.IndexOf(",\"", start);
  if (end < 0) throw new Exception("Cannot parse value: " + key);
  return json.Substring(start, end - start);
};
var changes = new List<object>();
string newJson = tgtJson;
foreach (var k in keys) {
  string oldV = tok(newJson, k), newV = tok(srcJson, k);
  if (oldV == newV) { changes.Add(new { setting = k, from = oldV, to = newV, changed = false }); continue; }
  string m = "\"" + k + "\":";
  newJson = newJson.Replace(m + oldV + ",\"", m + newV + ",\"");
  changes.Add(new { setting = k, from = oldV, to = newV, changed = true });
}
var tent = tgtDs.GetEntity(schema);
tent.Set<string>(field, newJson);
tgtDs.SetEntity(tent);
var verify = tgtDs.GetEntity(schema).Get<string>(field);
var mismatched = keys.Where(k => tok(verify, k) != tok(srcJson, k)).ToList();
if (mismatched.Count > 0) throw new Exception("Verification failed: " + string.Join(",", mismatched));
return new { target = tgtName, dataStorageId = tgtDs.Id.IntegerValue, phaseKept = tok(verify, "ActivePhaseId"), changes, verified = true };

int part = args != null && args.ContainsKey("part") ? Convert.ToInt32(args["part"]) : 0;
var groups = new SortedDictionary<string, List<int>>();
foreach (Element e in new FilteredElementCollector(doc).WhereElementIsNotElementType()) {
  if (e.Category == null || e.Category.CategoryType != CategoryType.Model || e.ViewSpecific) continue;
  var ip = e.LookupParameter("Export to IFC"); if (ip == null) continue;
  int iv = ip.HasValue ? ip.AsInteger() : 0;
  ElementType t = doc.GetElement(e.GetTypeId()) as ElementType;
  string reason = null;
  if (iv == 2) reason = "I";
  else if (iv == 0 && t != null) { var tp = t.LookupParameter("Export Type to IFC"); if (tp != null && tp.HasValue && tp.AsInteger() == 2) reason = "T"; }
  if (reason == null) continue;
  string lvl = e.LevelId != ElementId.InvalidElementId && doc.GetElement(e.LevelId) != null ? doc.GetElement(e.LevelId).Name : "-";
  string key = e.Category.Name + "|" + (t != null ? t.FamilyName : "") + "|" + (t != null ? t.Name : "") + "|" + reason + "|" + lvl;
  if (!groups.ContainsKey(key)) groups[key] = new List<int>();
  groups[key].Add(e.Id.IntegerValue);
}
var all = groups.ToList();
int half = all.Count / 2;
var sel = part == 0 ? all.Take(half) : all.Skip(half);
return new { totalGroups = all.Count, rows = sel.Select(g => g.Key + "#" + string.Join(",", g.Value)).ToList() };

