var res = new List<object>();
var col = new FilteredElementCollector(doc).WhereElementIsNotElementType();
foreach (Element e in col) {
  if (e.Category == null || e.Category.CategoryType != CategoryType.Model) continue;
  if (e.ViewSpecific) continue;
  var ip = e.LookupParameter("Export to IFC");
  if (ip == null) continue;
  int iv = ip.HasValue ? ip.AsInteger() : 0; // 0 = By Type, 1 = Export, 2 = Don't export
  string reason = null;
  ElementType t = doc.GetElement(e.GetTypeId()) as ElementType;
  if (iv == 2) reason = "Instance: Export to IFC = Don't Export";
  else if (iv == 0 && t != null) {
    var tp = t.LookupParameter("Export Type to IFC");
    if (tp != null && tp.HasValue && tp.AsInteger() == 2) reason = "Type: Export Type to IFC = Don't Export";
    else if (tp != null && tp.HasValue && tp.AsInteger() == 0 && tp.AsValueString() == "No") reason = "Type: Export Type to IFC = No";
  }
  if (reason == null) continue;
  string fam = (t as FamilySymbol) != null ? ((FamilySymbol)t).FamilyName : (t != null ? t.FamilyName : "");
  bool inPlace = (e is FamilyInstance) && ((FamilyInstance)e).Symbol.Family.IsInPlace;
  string lvl = "";
  if (e.LevelId != ElementId.InvalidElementId) { var l = doc.GetElement(e.LevelId); if (l != null) lvl = l.Name; }
  var tpv = t != null ? t.LookupParameter("Export Type to IFC") : null;
