Func<XYZ,XYZ> F = p => new XYZ(p.X, p.Y, level.Elevation);
var closedLoops = new List<List<Curve>>(); var pieces = new List<List<Curve>>();
foreach (var g in imp.get_Geometry(new Options())) {
  var gi = g as GeometryInstance; if (gi == null) continue;
  foreach (var o in gi.GetInstanceGeometry()) {
    var gs = doc.GetElement(o.GraphicsStyleId) as GraphicsStyle;
    if (gs == null || gs.GraphicsStyleCategory == null || gs.GraphicsStyleCategory.Name != layerName) continue;
    if (o is PolyLine pl) {
      var pts = pl.GetCoordinates().Select(F).ToList(); var segs = new List<Curve>();
      for (int k = 0; k < pts.Count - 1; k++) if (pts[k].DistanceTo(pts[k+1]) > shortTol) segs.Add(Line.CreateBound(pts[k], pts[k+1]));
      if (segs.Count == 0) continue;
      if (pts.Count > 2 && pts[0].DistanceTo(pts[pts.Count-1]) < tol) closedLoops.Add(segs); else pieces.Add(segs);
    } else if (o is Arc a) {
      var s = F(a.GetEndPoint(0)); var e = F(a.GetEndPoint(1)); if (s.DistanceTo(e) < tol) continue;
      pieces.Add(new List<Curve> { Arc.Create(s, e, F(a.Evaluate(0.5, true))) });
    } else if (o is Line ln) {
      var s = F(ln.GetEndPoint(0)); var e = F(ln.GetEndPoint(1));
