string cadName = args.ContainsKey("cadName") ? args["cadName"].ToString() : "Masterplan.dwg";
string layerName = args.ContainsKey("layer") ? args["layer"].ToString() : "BM_Plots-Boundaries";
double tol = 0.005; double shortTol = app.ShortCurveTolerance;
var imp = new FilteredElementCollector(doc).OfClass(typeof(ImportInstance)).Cast<ImportInstance>().FirstOrDefault(i => (doc.GetElement(i.GetTypeId())?.Name ?? "") == cadName);
Func<XYZ,XYZ> F = p => new XYZ(p.X, p.Y, 0);
var closedLoops = new List<List<Curve>>(); var pieces = new List<List<Curve>>();
foreach (var g in imp.get_Geometry(new Options())) {
  var gi = g as GeometryInstance; if (gi == null) continue;
  foreach (var o in gi.GetInstanceGeometry()) {
    var gs = doc.GetElement(o.GraphicsStyleId) as GraphicsStyle;
    if (gs == null || gs.GraphicsStyleCategory == null || gs.GraphicsStyleCategory.Name != layerName) continue;
    if (o is PolyLine pl) {
      var pts = pl.GetCoordinates().Select(F).ToList(); var segs = new List<Curve>();
      for (int k = 0; k < pts.Count - 1; k++) if (pts[k].DistanceTo(pts[k+1]) > shortTol) segs.Add(Line.CreateBound(pts[k], pts[k+1]));
      if (segs.Count == 0) continue;
      if (pts.Count > 2 && pts[0].DistanceTo(pts[pts.Count-1]) < tol) closedLoops.Add(segs); else pieces.Add(segs);
    } else if (o is Arc a) {
      var s = F(a.GetEndPoint(0)); var e = F(a.GetEndPoint(1)); if (s.DistanceTo(e) < tol) continue;
      pieces.Add(new List<Curve> { Arc.Create(s, e, F(a.Evaluate(0.5, true))) });
    } else if (o is Line ln) {
      var s = F(ln.GetEndPoint(0)); var e = F(ln.GetEndPoint(1));
      if (s.DistanceTo(e) > shortTol) pieces.Add(new List<Curve> { Line.CreateBound(s, e) });
    }
  }
}
var used = new bool[pieces.Count]; var chained = new List<List<Curve>>();
for (int i = 0; i < pieces.Count; i++) {
  if (used[i]) continue; used[i] = true;
  var chain = new List<Curve>(pieces[i]);
  XYZ start = chain[0].GetEndPoint(0), end = chain[chain.Count-1].GetEndPoint(1);
  bool closed = start.DistanceTo(end) < tol;
  while (!closed) {
    int found = -1; bool rev = false;
    for (int j = 0; j < pieces.Count; j++) {
      if (used[j]) continue;
      if (pieces[j][0].GetEndPoint(0).DistanceTo(end) < tol) { found = j; break; }
      if (pieces[j][pieces[j].Count-1].GetEndPoint(1).DistanceTo(end) < tol) { found = j; rev = true; break; }
    }
    if (found < 0) break;
    used[found] = true; var seg = pieces[found];
    if (rev) seg = seg.AsEnumerable().Reverse().Select(c => c.CreateReversed()).ToList();
    chain.AddRange(seg); end = chain[chain.Count-1].GetEndPoint(1); closed = start.DistanceTo(end) < tol;
  }
  if (closed) chained.Add(chain);
}
var bad = new List<object>(); int good = 0; int idx = 0;
foreach (var lc in closedLoops.Concat(chained)) {
  string src = idx < closedLoops.Count ? "polyline" : "chained"; idx++;
  var snapped = new List<Curve>(); XYZ prev = lc[0].GetEndPoint(0); XYZ first = prev;
  for (int k = 0; k < lc.Count; k++) {
    var c = lc[k]; XYZ e = (k == lc.Count-1) ? first : c.GetEndPoint(1);
    if (c is Arc) snapped.Add(Arc.Create(prev, e, c.Evaluate(0.5, true))); else snapped.Add(Line.CreateBound(prev, e));
    prev = e;
  }
  int selfX = 0;
  for (int m = 0; m < snapped.Count; m++) for (int n = m + 2; n < snapped.Count; n++) {
    if (m == 0 && n == snapped.Count - 1) continue;
    var r = snapped[m].Intersect(snapped[n]);
    if (r == SetComparisonResult.Overlap || r == SetComparisonResult.Equal || r == SetComparisonResult.Subset || r == SetComparisonResult.Superset) selfX++;
  }
  string ext = "ok";
  try { GeometryCreationUtilities.CreateExtrusionGeometry(new List<CurveLoop> { CurveLoop.Create(snapped) }, XYZ.BasisZ, 1.0); } catch (Exception ex) { ext = ex.Message; }
  if (selfX > 0 || ext != "ok") {
    var bb = snapped.SelectMany(c => c.Tessellate()).ToList();
    bad.Add(new { index = idx - 1, source = src, segments = snapped.Count, selfIntersections = selfX, extrusion = ext, centerX_m = Math.Round(bb.Average(p => p.X) * 0.3048, 2), centerY_m = Math.Round(bb.Average(p => p.Y) * 0.3048, 2) });
  } else good++;
}
return new { goodLoops = good, badLoops = bad };

