Func<double[,], CurveLoop> buildLoop = (pts) => {
    var loop = new CurveLoop();
    int n = pts.GetLength(0);
    var xyzs = new XYZ[n];
    for (int i = 0; i < n; i++) xyzs[i] = new XYZ(pts[i,0], pts[i,1], 0);
    for (int i = 0; i < n; i++) loop.Append(Line.CreateBound(xyzs[i], xyzs[(i+1)%n]));
    return loop;
};

